#include <stdio.h>
#include <string.h>

static unsigned char adj[1001][1001];
static int seq[1001];

int main(void) {
    int S, T;
    if (scanf("%d %d", &S, &T) != 2) return 0;
    for (int i = 0; i < T; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        adj[x][y] = 1;
        adj[y][x] = 1;
    }
    int P, count = 0;
    scanf("%d", &P);
    while (P--) {
        int N;
        scanf("%d", &N);
        for (int i = 0; i < N; i++) scanf("%d", &seq[i]);
        int ok = 1;
        for (int i = 1; i < N; i++) {
            if (!adj[seq[i-1]][seq[i]]) { ok = 0; break; }
        }
        if (ok) count++;
    }
    printf("%d\n", count);
    return 0;
}
